 text=e.get_text(' ',strip=True);(C/('2026-04_'+hashlib.sha256(a['url'].encode()).hexdigest()[:16]+'.txt')).write_text(text);a['retrieval']='Public body retrieved; selected lead/substantive passages inspected only';a['words']=len(text.split());return a,re.split(r'Posted \d+ \w+ \d{4}',text,maxsplit=1)[-1]
